-- horse: 17 row(s)
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (1, 'Peanut', 'kids', 'Tiny, patient pony who loves children', 'Kid-friendly ponies', 45, 'available', '', NULL, 1, 'Shetland pony', 'Chestnut', 'gelding', 2012, '10.2', 2018, 'Peanut spent his early years at a children''s riding school, where he taught hundreds of little riders their very first trot. He came to us to enjoy a slower pace and now leads our youngest beach riders with endless patience.', 'Peanut is the smallest member of the herd and the bossiest at feeding time.', 'Apple slices');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (2, 'Biscuit', 'kids', 'Gentle and easy to lead', 'Kid-friendly ponies', 50, 'available', '', NULL, 1, 'Welsh pony', 'Dun', 'mare', 2014, '12.1', 2019, 'Biscuit was a Pony Club all-rounder before joining Seahorse. She loves children, stands like a statue for photos, and is always first to the gate when the kids arrive.', 'She got her name because she can hear a biscuit packet open from across the paddock.', 'Ginger biscuits (of course)');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (3, 'Pebbles', 'kids', 'Calm Shetland cross, great with first-timers', 'Kid-friendly ponies', 45, 'available', '', NULL, 1, 'Shetland cross', 'Grey', 'mare', 2015, '11.0', 2020, 'Pebbles was rescued as a youngster and lovingly retrained by our team. She''s gentle, steady and especially good with nervous first-time little riders.', 'Pebbles collects shells — or at least stands on them and refuses to move until you admire them.', 'Carrots');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (4, 'Coco', 'kids', 'Sweet-natured pony', 'Kid-friendly ponies', 55, 'available', '', NULL, 1, 'Basuto pony', 'Brown', 'mare', 2013, '13.2', 2017, 'Basuto ponies are famous for being hardy and kind, and Coco is no exception. She was bred in the Free State and moved to the coast to become our favourite pony for older children.', 'Coco is a true South African pony — sure-footed on sand, rocks and dunes.', 'Peppermints');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (5, 'Willow', 'nervous', 'Our steadiest mare — unflappable on the beach', 'Extra-calm horses', 85, 'available', '', NULL, 1, 'Arabian cross', 'Grey', 'mare', 2009, '14.3', 2016, 'Willow is our most trusted horse for nervous riders. She was an endurance horse in her younger days and now prefers calm walks along the water''s edge, where she looks after her riders like family.', 'Willow has walked the shoreline more times than anyone can count — nothing on the beach surprises her.', 'Watermelon rind');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (6, 'Sage', 'nervous', 'Slow, careful and kind', 'Extra-calm horses', 85, 'available', '', NULL, 1, 'Boerperd', 'Bay', 'gelding', 2010, '15.0', 2017, 'The Boerperd is South Africa''s own breed, known for good sense and stamina. Sage worked on a farm in the Karoo before retiring to the coast, and he''s unflappable around waves, dogs and kites.', 'Sage gives a gentle nose-nudge to every rider before they mount — guides call it his safety check.', 'Hay cubes');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (7, 'Honey', 'nervous', 'Relaxed and reassuring', 'Extra-calm horses', 80, 'available', '', NULL, 1, 'Palomino Quarter Horse', 'Palomino', 'mare', 2012, '14.2', 2019, 'Honey came from a trail-riding centre in the Midlands. She has a relaxed, comfortable walk and a soothing nature that settles even the most anxious riders.', 'Honey''s golden coat glows at sunset — she''s the star of most of our couples'' photos.', 'Honey-oat treats');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (8, 'Storm', 'beginner', 'Calm, steady beach horse', 'Beginner-friendly horses', 95, 'available', '', NULL, 1, 'Thoroughbred cross', 'Dark bay', 'gelding', 2011, '15.3', 2018, 'Storm raced briefly before discovering he much preferred strolling. Retrained for beach work, he''s become our go-to horse for adult beginners.', 'Despite his name, Storm is the calmest horse on the beach — he naps standing up between rides.', 'Apples');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (9, 'Coral', 'beginner', 'Gentle and good with groups', 'Beginner-friendly horses', 90, 'available', '', NULL, 1, 'Boerperd', 'Chestnut', 'mare', 2013, '15.1', 2018, 'Coral grew up near the sea and has been part of the Seahorse herd for years. She''s gentle in a group and happy to follow the leader, which makes her perfect for families and friends riding together.', 'Coral loves splashing through the shallows and will happily paddle on a hot day.', 'Carrots');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (10, 'Sandy', 'beginner', 'Follows the leader happily', 'Beginner-friendly horses', 90, 'available', '', NULL, 1, 'Appaloosa cross', 'Spotted dun', 'gelding', 2014, '14.3', 2020, 'Sandy joined us from a holiday farm where he carried guests of every age. He''s patient, steady and always keeps a polite distance from the horse in front.', 'Every one of Sandy''s spots is different — kids love trying to count them.', 'Bananas');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (11, 'Misty', 'beginner', 'Quiet and willing', 'Beginner-friendly horses', 90, 'available', '', NULL, 1, 'Connemara cross', 'Grey', 'mare', 2012, '14.2', 2019, 'Connemaras are known for their kind temperament, and Misty is a classic example — quiet, willing and happy to go at whatever pace her rider is comfortable with.', 'Misty turns almost white in winter and dapples again by summer.', 'Pears');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (12, 'Shadow', 'beginner', 'Easy-going gelding', 'Beginner-friendly horses', 95, 'available', '', NULL, 1, 'Friesian cross', 'Black', 'gelding', 2013, '15.2', 2019, 'Shadow came to us as a shy youngster and has grown into one of our most dependable beginner horses. His striking black coat looks spectacular against the white surf.', 'Shadow''s long, wavy mane needs more brushing than anyone else''s — he loves the attention.', 'Sugar-free mints');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (13, 'Breeze', 'confident', 'Forward-going, loves a canter', 'Horses for confident riders', 90, 'available', '', NULL, 1, 'Arabian', 'Bay', 'mare', 2014, '15.0', 2020, 'Breeze is light, quick and responsive, and for experienced riders a canter with her along the firm sand is unforgettable. Our guides only pair her with confident riders.', 'Breeze has competed in endurance rides through the mountains — she still loves an adventure.', 'Dates');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (14, 'Blaze', 'confident', 'Energetic and responsive', 'Horses for confident riders', 85, 'available', '', NULL, 1, 'Thoroughbred', 'Chestnut', 'gelding', 2012, '16.1', 2019, 'An ex-racehorse with plenty of energy, Blaze was retrained by our head guide over two years. He now channels his enthusiasm into beach canters with experienced riders.', 'Blaze gets his name from the bright white stripe running down his face.', 'Polo mints');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (15, 'Tide', 'confident', 'Athletic beach galloper', 'Horses for confident riders', 90, 'available', '', NULL, 1, 'Warmblood', 'Bay', 'gelding', 2011, '16.2', 2018, 'Tide was a show jumper before choosing the beach life. Athletic and powerful, he''s the horse our guides ride themselves on their days off.', 'Tide was born on the night of a spring tide — hence the name.', 'Apples and carrots');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (16, 'Atlas', 'sturdy', 'Big, strong and gentle', 'Sturdy horses for taller riders', 115, 'available', '', NULL, 1, 'Shire cross', 'Black and white', 'gelding', 2010, '17.0', 2017, 'Our gentle giant, Atlas, worked on a forestry farm before joining us. He''s strong enough to carry taller and heavier riders comfortably, and he has the softest nature in the herd.', 'Atlas''s hooves are the size of dinner plates — people often stop just to take a photo with him.', 'Whole carrots, in one bite');
INSERT INTO `horse` (`id`, `name`, `category`, `temperament`, `suitable_for`, `max_rider_weight_kg`, `status`, `notes`, `photo_path`, `show_publicly`, `breed`, `colour`, `sex`, `birth_year`, `height_hands`, `joined_year`, `history`, `fun_fact`, `favourite_treat`) VALUES (17, 'Duke', 'sturdy', 'Sturdy draught cross, very calm', 'Sturdy horses for taller riders', 120, 'available', '', NULL, 1, 'Clydesdale cross', 'Bay roan', 'gelding', 2012, '16.3', 2019, 'Duke is calm, solid and steady — the horse we choose for riders who want to feel secure on a big, reliable mount. He loves a good scratch behind the ears after a ride.', 'Duke has fluffy feathered legs that get comically sandy after every ride.', 'Pumpkin');

